interface ExamQuestionProps {
  number: number;
  title: string;
  content: string;
  isAvailable: boolean;
}

const ExamQuestion: React.FC<ExamQuestionProps> = ({ number, title, content, isAvailable }) => {
  const [isAnswering, setIsAnswering] = useState(false);
  const [answer, setAnswer] = useState('');
  const [feedback, setFeedback] = useState<ExamFeedback | null>(null);
  const [isGrading, setIsGrading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGrade = async () => {
    if (!answer.trim() || !isAvailable) return;
    setIsGrading(true);
    setError(null);

    try {
      // FIX: Service now pulls process.env.API_KEY directly.
      const result = await gradeExamAnswer({ title, content }, answer);
      if (result) {
        setFeedback(result);
      } else {
        setError("Could not grade the answer. Please try again.");
      }
    } catch (err) {
      setError(getFriendlyErrorMessage(err));
    } finally {
      setIsGrading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, x: -30 }}
      whileInView={{ opacity: 1, x: 0 }}
      viewport={{ once: true, amount: 0.2 }}
      transition={{ duration: 0.6 }}
      className="bg-white p-6 sm:p-8 rounded-lg shadow-md border-l-4 border-black"
    >
