import { User } from '../types';
import { generateSecureId, isValidEmail } from './securityService';

const USERS_KEY = 'kazira_users_db';
const SESSION_KEY = 'kazira_session_user_id';
const MOCK_LATENCY = 300; 

const simulate = <T>(data: T): Promise<T> => {
  return new Promise(resolve => setTimeout(() => resolve(data), MOCK_LATENCY));
};

const getUsersDB = (): Record<string, User> => {
  try {
    const db = localStorage.getItem(USERS_KEY);
    return db ? JSON.parse(db) : {};
  } catch (e) {
    return {};
  }
};

const saveUsersDB = (db: Record<string, User>): void => {
  localStorage.setItem(USERS_KEY, JSON.stringify(db));
};

/**
 * Handles login via email or as an anonymous explorer.
 * Guest email logins are deprecated in favor of Explorer access and Update collection.
 */
export const loginUser = async (email: string, isExplorer: boolean = false): Promise<User | null> => {
  const db = getUsersDB();

  // For prototype purposes, explorer is the primary entry point.
  // We keep the architecture for typed users for future integration.
  const targetEmail = isExplorer ? 'explorer@kazira.io' : email.toLowerCase();

  // Basic validation if email is provided
  if (!isExplorer && !isValidEmail(targetEmail)) {
     return simulate(null);
  }

  let user = Object.values(db).find(u => u.email.toLowerCase() === targetEmail);

  if (!user) {
    const id = isExplorer ? 'explorer_id' : generateSecureId();
    const name = isExplorer ? 'Explorer' : targetEmail.split('@')[0].replace(/[^a-zA-Z0-9]/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
    user = { 
      id, 
      name, 
      email: targetEmail, 
      bio: isExplorer ? 'I am exploring Kazira.io features anonymously.' : '' 
    };
    db[id] = user;
    saveUsersDB(db);
  }

  localStorage.setItem(SESSION_KEY, user.id);
  return simulate(user);
};

export const logoutUser = async (): Promise<void> => {
  localStorage.removeItem(SESSION_KEY);
  return simulate(undefined);
};

export const getSessionUser = async (): Promise<User | null> => {
  const userId = localStorage.getItem(SESSION_KEY);
  if (!userId) return simulate(null);

  const db = getUsersDB();
  const user = db[userId] || null;

  if (!user) {
    localStorage.removeItem(SESSION_KEY);
  }

  return simulate(user);
};

export const updateUserProfile = async (updatedData: Partial<User>): Promise<User | null> => {
  const userId = localStorage.getItem(SESSION_KEY);
  if (!userId) return simulate(null);

  const db = getUsersDB();
  const user = db[userId];

  if (!user) {
    localStorage.removeItem(SESSION_KEY);
    return simulate(null);
  }

  // SECURITY: Strictly allow only specific fields to be updated
  const newUserData = { 
    ...user,
    name: updatedData.name ? updatedData.name.slice(0, 100) : user.name,
    bio: updatedData.bio !== undefined ? updatedData.bio.slice(0, 500) : user.bio,
  };
  db[userId] = newUserData;
  saveUsersDB(db);

  return simulate(newUserData);
};

import React, { ErrorInfo, ReactNode } from 'react';
import Button from './Button';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

/**
 * ErrorBoundary component to catch rendering errors in the component tree.
 * Inheriting from React.Component with specified generic types (Props, State) 
 * ensures that 'this.props' and 'this.state' are correctly recognized by the TypeScript compiler.
 */
class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: undefined,
  };

  constructor(props: Props) {
    super(props);
  }

  // Static method used to update state after an error has been thrown by a descendant component.
  static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  // Lifecycle method for logging error information and performing side effects.
  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Standard error logging for debugging purposes
    console.error("Uncaught error captured by boundary:", error, errorInfo);
  }

  // Helper method to refresh the application state by reloading the page.
  private handleRefresh = () => {
    // Attempt to recover by reloading the application context
    window.location.reload();
  };

  public render(): ReactNode {
    const { hasError, error } = this.state;

    if (hasError) {
      // Graceful fallback UI for production reliability
      return (
        <div className="container mx-auto px-4 py-16 text-center" role="alert">
          <div className="bg-gray-100 border border-gray-400 text-gray-700 px-4 py-8 rounded-lg relative max-w-lg mx-auto shadow-lg">
            <h2 className="text-2xl font-bold mb-4">We've Hit a Snag!</h2>
            <p className="mb-6">An unexpected error occurred. Our team has been notified, but a quick refresh of the page often fixes the issue.</p>
            <details className="text-left text-sm bg-gray-200 p-3 rounded-md mb-6 max-w-full overflow-auto">
              <summary className="cursor-pointer font-semibold">Error Details</summary>
              <pre className="mt-2 whitespace-pre-wrap break-all font-mono text-xs">
                <code>
                  {error?.toString()}
                </code>
              </pre>
            </details>
            <Button
              onClick={this.handleRefresh}
              variant="primary"
            >
              Refresh Page
            </Button>
          </div>
        </div>
      );
    }

    /**
     * FIX: Inheritance from React.Component<Props, State> correctly provides 'this.props'.
     * This avoids the "Property 'props' does not exist on type 'ErrorBoundary'" error.
     */
    return this.props.children;
  }
}

export default ErrorBoundary;

