              <pre className="mt-2 whitespace-pre-wrap break-all font-mono text-xs">
                <code>
                  {error?.toString()}
                </code>
              </pre>
            </details>
            <Button
              onClick={this.handleRefresh}
              variant="primary"
            >
              Refresh Page
            </Button>
          </div>
        </div>
      );
    }

    // Accessing this.props.children through destructuring to satisfy compiler checks and provide safe rendering.
    const { children } = this.props;
    return children || null;
  }
}

